// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/**
 * @title SingleProjectContract
 * @dev Отдельный контракт для одного проекта пожертвований
 * 
 * Каждый проект имеет свой собственный контракт, что обеспечивает полную изоляцию
 */
contract SingleProjectContract {
    // Владелец контракта (адрес фонда)
    address public owner;
    
    // Название проекта
    string public projectName;
    
    // Целевая сумма для сбора (в wei)
    uint256 public targetAmount;
    
    // Собранная сумма (в wei)
    uint256 public collectedAmount;
    
    // Активен ли проект
    bool public isActive;
    
    // Кошелек проекта (для вывода средств)
    address public projectWallet;
    
    // Структура пожертвования
    struct Donation {
        address donor;           // Адрес донора
        uint256 amount;          // Сумма пожертвования (в wei)
        uint256 timestamp;       // Время пожертвования
        bool isAnonymous;        // Анонимное пожертвование или нет
    }
    
    // Маппинг для хранения всех пожертвований (индекс => Donation)
    mapping(uint256 => Donation) public donations;
    
    // Счетчик пожертвований
    uint256 public donationCount;
    
    // Маппинг общей суммы пожертвований от каждого донора
    mapping(address => uint256) public donorTotalAmount;
    
    // События
    event ProjectCreated(string name, uint256 targetAmount, address projectWallet);
    event Donated(address indexed donor, uint256 amount, uint256 timestamp, bool isAnonymous);
    event FundsWithdrawn(address indexed to, uint256 amount);
    event ProjectStatusChanged(bool isActive);
    
    /**
     * @dev Конструктор контракта проекта
     * @param _projectName Название проекта
     * @param _targetAmount Целевая сумма для сбора в wei
     * @param _projectWallet Адрес кошелька, на который будут выводиться средства проекта
     * @param _owner Владелец контракта (адрес фабрики)
     */
    constructor(
        string memory _projectName,
        uint256 _targetAmount,
        address _projectWallet,
        address _owner
    ) {
        owner = _owner;
        projectName = _projectName;
        targetAmount = _targetAmount;
        projectWallet = _projectWallet;
        collectedAmount = 0;
        isActive = true;
        donationCount = 0;
        
        emit ProjectCreated(_projectName, _targetAmount, _projectWallet);
    }
    
    // Модификатор для ограничения доступа только владельцу
    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }
    
    /**
     * @dev Позволяет пользователям делать пожертвования на проект
     * @param _isAnonymous Флаг, указывающий, является ли пожертвование анонимным
     */
    function donate(bool _isAnonymous) public payable {
        require(msg.value > 0, "Donation amount must be greater than zero");
        require(isActive, "Project is not active");
        
        collectedAmount += msg.value;
        donationCount++;
        
        donations[donationCount] = Donation(
            msg.sender,
            msg.value,
            block.timestamp,
            _isAnonymous
        );
        
        donorTotalAmount[msg.sender] += msg.value;
        
        emit Donated(msg.sender, msg.value, block.timestamp, _isAnonymous);
    }
    
    /**
     * @dev Возвращает информацию о конкретном пожертвовании
     * @param _donationId ID пожертвования
     * @return donor Адрес донора
     * @return amount Сумма пожертвования
     * @return timestamp Время пожертвования
     * @return isAnonymous Анонимное ли пожертвование
     */
    function getDonation(uint256 _donationId) public view returns (
        address donor,
        uint256 amount,
        uint256 timestamp,
        bool isAnonymous
    ) {
        require(donations[_donationId].donor != address(0), "Donation does not exist");
        Donation storage donation = donations[_donationId];
        return (donation.donor, donation.amount, donation.timestamp, donation.isAnonymous);
    }
    
    /**
     * @dev Позволяет владельцу вывести средства проекта
     * @param _amount Сумма для вывода в wei
     */
    function withdrawFunds(uint256 _amount) public onlyOwner {
        require(collectedAmount >= _amount, "Insufficient collected funds");
        require(_amount > 0, "Amount must be greater than zero");
        
        collectedAmount -= _amount;
        payable(projectWallet).transfer(_amount);
        emit FundsWithdrawn(projectWallet, _amount);
    }
    
    /**
     * @dev Позволяет владельцу изменить статус активности проекта
     * @param _isActive Новый статус активности
     */
    function setProjectStatus(bool _isActive) public onlyOwner {
        isActive = _isActive;
        emit ProjectStatusChanged(_isActive);
    }
    
    /**
     * @dev Возвращает текущий баланс контракта
     * @return Баланс контракта в wei
     */
    function getContractBalance() public view returns (uint256) {
        return address(this).balance;
    }
    
    /**
     * @dev Возвращает процент выполнения цели проекта
     * @return Процент выполнения цели (0-100)
     */
    function getProgress() public view returns (uint256) {
        if (targetAmount == 0) {
            return 0;
        }
        return (collectedAmount * 100) / targetAmount;
    }
    
    /**
     * @dev Возвращает полную информацию о проекте
     * @return name Название проекта
     * @return target Целевая сумма
     * @return collected Собранная сумма
     * @return active Активен ли проект
     * @return wallet Кошелек проекта
     * @return progress Процент выполнения
     */
    function getProjectInfo() public view returns (
        string memory name,
        uint256 target,
        uint256 collected,
        bool active,
        address wallet,
        uint256 progress
    ) {
        return (
            projectName,
            targetAmount,
            collectedAmount,
            isActive,
            projectWallet,
            getProgress()
        );
    }
}

